    /**
    * Calls:
    * (400) POST:/WebGoat/csrf/feedback/message
    * Found 1 potential fault of type-code 200
    */
    @Test @Timeout(60)
    fun test_143_postOnMessageReturnsMismatchResponseWithSchema()  {
        
        val cookies_userB : Map<String,String> = given()
            .contentType("application/x-www-form-urlencoded")
            .body("username=userbb&password=userBB")
            .post("${baseUrlOfSut}/WebGoat/login")
            .then().extract().cookies()
            
        
        // Fault200. Schema Violation: Received A Response From API With A Structure/Data That Is Not Matching Its Schema. Type: validation.response.status.unknown Response status 400 not defined for path '/csrf/feedback/message'.
        given().accept("application/json")
                .cookies(cookies_userB)
                .contentType("application/json")
                .post("${baseUrlOfSut}/WebGoat/csrf/feedback/message")
                .then()
                .statusCode(400)
                .assertThat()
                .contentType("application/json")
                .body("'status'", numberMatches(400))
                .body("'error'", containsString("Bad Request"))
                .body("'path'", containsString("/WebGoat/csrf/feedback/message"))
    }
    
    
    /**
    * Calls:
    * (401) POST:/WebGoat/JWT/refresh/checkout
    * Found 3 potential faults. Type-codes: 109, 200, 202
    */
    @Test @Timeout(60)
    fun test_144_postOnCheckoutShowsFaults_109_200_202()  {
        
        val cookies_userB : Map<String,String> = given()
            .contentType("application/x-www-form-urlencoded")
            .body("username=userbb&password=userBB")
            .post("${baseUrlOfSut}/WebGoat/login")
            .then().extract().cookies()
            
        
        // Fault109. HTTP Violation: no-401-if-no-authenticate.
        // Fault200. Schema Violation: Received A Response From API With A Structure/Data That Is Not Matching Its Schema. Type: validation.response.status.unknown Response status 401 not defined for path '/JWT/refresh/checkout'.
        // Fault202. Schema Violation: no-401-if-no-auth.
        given().accept("*/*")
                .cookies(cookies_userB)
                .noContentType()
                .post("${baseUrlOfSut}/WebGoat/JWT/refresh/checkout")
                .then()
                .statusCode(401)
                .assertThat()
                .header("www-authenticate", isEmptyOrNullString())
                .body(isEmptyOrNullString())
    }


